def merge_deltas(original: dict, delta: dict) -> dict:
    """
    将 OpenAI 流式响应的 delta 合并进 original 消息对象。

    规则：
    - None 值：**不覆盖**已有非 None 值（qwen-plus 等兼容 API 在每个 chunk 中
      为未变化的字段发送 None，若直接覆盖会清除已累积的内容）
    - dict 类型：递归合并
    - list 类型（tool_calls）：按 index 字段进行位置合并
    - str / 其他类型：若已有同类型则拼接（+=），否则直接赋值

    Examples
    --------
    >>> merge_deltas({}, {"role": "assistant"})
    {'role': 'assistant'}
    >>> merge_deltas({"content": "hello"}, {"content": " world"})
    {'content': 'hello world'}
    >>> merge_deltas({"content": "hi"}, {"content": None})
    {'content': 'hi'}
    """
    logger.debug(f"merge_deltas: delta_keys={list(delta.keys())}")
    try:
        if original is None:
            original = {}

        for key, value in delta.items():
            # ── None：不覆盖已有非 None 值 ──────────────────────
            if value is None:
                if key not in original:
                    original[key] = None
                # else: 保留已有值，忽略 None delta
                continue

            # ── list（tool_calls 流式合并）────────────────────────
            if isinstance(value, list):
                if key not in original or original[key] is None:
                    original[key] = []
                existing_list = original[key]

                for item in value:
                    if not isinstance(item, dict):
                        # 普通列表直接追加
                        existing_list.append(item)
                        continue

                    # tool_calls 用 index 字段定位
                    idx = item.get("index")
                    if idx is None:
                        existing_list.append(item)
                        continue

                    # 扩展列表至所需长度
                    while len(existing_list) <= idx:
                        existing_list.append({})

                    # 递归合并该 index 处的对象（去掉 index 字段本身）
                    item_without_index = {k: v for k, v in item.items() if k != "index"}
                    merge_deltas(existing_list[idx], item_without_index)
                continue

            # ── dict：递归合并 ────────────────────────────────────
            if isinstance(value, dict):
                if key not in original or original[key] is None:
                    original[key] = {}
                merge_deltas(original[key], value)
                continue

            # ── 标量（str / int / bool）──────────────────────────
            existing = original.get(key)
            if existing is not None and type(existing) == type(value):
                # 同类型则拼接（适用于 content / arguments 字符串流式累积）
                try:
                    original[key] = existing + value
                except TypeError:
                    original[key] = value  # 不可拼接则直接覆盖
            else:
                original[key] = value

        return original

    except Exception:
        exc_type, exc_value, exc_traceback = sys.exc_info()
        error_message = repr(traceback.format_exception(exc_type, exc_value, exc_traceback))
        logger.error(f"[json_utils] merge_deltas 失败: {error_message}")
        raise

