"""
utils/json_utils.py — JSON 工具函数

- merge_deltas: 合并 OpenAI / 兼容 API 流式 delta（支持 tool_calls、None 防覆盖）
- parse_partial_json: 容错解析不完整 JSON（流式 function_call / tool_calls arguments）
- escape_newlines_in_json_string_values: 修复 JSON 字符串中的裸换行符
"""

from __future__ import annotations

import json
import re
import sys
import traceback
from typing import Any

from loguru import logger


# ── merge_deltas ────────────────────────────────────────────────

def merge_deltas(original: dict, delta: dict) -> dict:
    """
    将 OpenAI 流式响应的 delta 合并进 original 消息对象。

    关键规则：
    1. **None 不覆盖非 None**：qwen-plus / DashScope 等兼容 API 在每个 chunk 的
       delta 中，未变化的字段会发送 None。若直接覆盖会清除已累积的内容。
    2. **list（tool_calls）按 index 合并**：OpenAI streaming 的 tool_calls
       通过 index 字段标识每个工具调用的位置，需要位置合并而非追加。
    3. **dict 递归合并**。
    4. **标量同类型拼接**（str += str，适用于 content / arguments 流式累积）。

    Examples
    --------
    >>> merge_deltas({}, {"role": "assistant"})
    {'role': 'assistant'}
    >>> merge_deltas({"content": "hello"}, {"content": " world"})
    {'content': 'hello world'}
    >>> merge_deltas({"content": "hi"}, {"content": None})  # None 不覆盖
    {'content': 'hi'}
    """
    logger.debug(f"merge_deltas: delta_keys={list(delta.keys())}")
    try:
        if original is None:
            original = {}

        for key, value in delta.items():

            # ── 1. None：不覆盖已有非 None 值 ──────────────────
            if value is None:
                if key not in original:
                    original[key] = None
                # else: 保留已有值，忽略 None delta
                continue

            # ── 2. list（tool_calls 按 index 流式合并）──────────
            if isinstance(value, list):
                if key not in original or original[key] is None:
                    original[key] = []
                existing_list = original[key]

                for item in value:
                    if not isinstance(item, dict):
                        existing_list.append(item)
                        continue

                    idx = item.get("index")
                    if idx is None:
                        existing_list.append(item)
                        continue

                    # 扩展至所需长度
                    while len(existing_list) <= idx:
                        existing_list.append({})

                    # 递归合并（去掉 index 字段）
                    item_no_idx = {k: v for k, v in item.items() if k != "index"}
                    merge_deltas(existing_list[idx], item_no_idx)
                continue

            # ── 3. dict 递归合并 ─────────────────────────────────
            if isinstance(value, dict):
                if key not in original or original[key] is None:
                    original[key] = {}
                merge_deltas(original[key], value)
                continue

            # ── 4. 标量：同类型则拼接，否则覆盖 ────────────────────
            existing = original.get(key)
            if existing is not None and type(existing) is type(value):
                try:
                    original[key] = existing + value
                except TypeError:
                    original[key] = value
            else:
                original[key] = value

        return original

    except Exception:
        exc_type, exc_value, exc_traceback = sys.exc_info()
        error_message = repr(traceback.format_exception(exc_type, exc_value, exc_traceback))
        logger.error(f"[json_utils] merge_deltas 失败: {error_message}")
        raise


# ── escape_newlines_in_json_string_values ───────────────────────

def escape_newlines_in_json_string_values(s: str) -> str:
    """将 JSON 字符串值内部的裸换行符转义为 \\n，修复流式 function_call arguments。"""
    result: list[str] = []
    in_string = False

    for ch in s:
        if ch == '"' and (not result or result[-1] != "\\"):
            in_string = not in_string
        if in_string and ch == "\n":
            result.append("\\n")
        else:
            result.append(ch)

    return "".join(result)


# ── parse_partial_json ──────────────────────────────────────────

def parse_partial_json(s: str) -> Any | None:
    """
    容错解析可能不完整的 JSON 字符串（流式 function_call / tool_calls arguments）。

    策略：
    1. 直接 json.loads
    2. 修复裸换行 + 补全括号/引号
    3. 正则提取关键字段（language / code）

    Returns None 表示解析失败（不抛出异常）。
    """
    logger.debug(f"parse_partial_json: input_length={len(s)}")

    if not s or not s.strip():
        return None

    # 1. 直接解析
    try:
        return json.loads(s)
    except json.JSONDecodeError:
        pass

    # 2. 修复裸换行
    s2 = escape_newlines_in_json_string_values(s)

    # 3. 追踪结构，补全括号/引号
    stack: list[str] = []
    in_string = False
    escaped = False

    for char in s2:
        if escaped:
            escaped = False
            continue
        if char == "\\":
            escaped = True
        elif char == '"' and not escaped:
            in_string = not in_string
        elif not in_string:
            if char in ("{", "["):
                stack.append(char)
            elif char == "}" and stack and stack[-1] == "{":
                stack.pop()
            elif char == "]" and stack and stack[-1] == "[":
                stack.pop()

    completed = s2
    if in_string:
        completed += '"'
    while stack:
        completed += "}" if stack.pop() == "{" else "]"

    try:
        return json.loads(completed)
    except json.JSONDecodeError:
        pass

    # 4. 正则提取关键字段（兜底）
    result_dict: dict = {}

    lang_match = re.search(r'"language"\s*:\s*"([^"]*)"', s)
    if lang_match:
        result_dict["language"] = lang_match.group(1)

    # 提取 code 字段（可能不完整）
    code_match = re.search(r'"code"\s*:\s*"((?:[^"\\]|\\.)*)', s, re.DOTALL)
    if code_match:
        result_dict["code"] = code_match.group(1)

    if result_dict:
        return result_dict

    if len(s) > 15:
        logger.warning(f"parse_partial_json: 无法解析，返回 None. snippet={s[:80]!r}")
    return None


# ── 从消息对象提取 language + code ──────────────────────────────

def extract_code_from_message(message: dict) -> tuple[str, str]:
    """
    从 LLM 消息对象提取 (language, code)。

    同时支持：
    - 现代 tool_calls 格式（OpenAI >= 1.0，DashScope qwen 等）
    - 传统 function_call 格式（旧版 OpenAI API）

    Returns
    -------
    (language, code) — 任一为空字符串表示未找到
    """
    # ── tool_calls 格式（优先）───────────────────────────────────
    tc_list = message.get("tool_calls") or []
    if isinstance(tc_list, list):
        for tc in tc_list:
            if not isinstance(tc, dict):
                continue
            if tc.get("type") != "function":
                continue
            func = tc.get("function") or {}
            # 先尝试已解析好的 parsed_arguments
            parsed = func.get("parsed_arguments")
            if not parsed and func.get("arguments"):
                parsed = parse_partial_json(func["arguments"])
            if parsed and isinstance(parsed, dict):
                lang = parsed.get("language") or "python"
                code = parsed.get("code") or ""
                if code:
                    return lang, code

    # ── function_call 格式（传统）────────────────────────────────
    fc = message.get("function_call") or {}
    if isinstance(fc, dict):
        parsed = fc.get("parsed_arguments")
        if not parsed and fc.get("arguments"):
            parsed = parse_partial_json(fc["arguments"])
        if parsed and isinstance(parsed, dict):
            lang = parsed.get("language") or "python"
            code = parsed.get("code") or ""
            if code:
                return lang, code

    return "", ""


# ── standalone 演示 ─────────────────────────────────────────────
if __name__ == "__main__":
    # ── merge_deltas 演示 ────────────────────────────────────────
    print("=== merge_deltas ===")
    msg: dict = {}
    # 模拟 qwen-plus 风格：每个 chunk 都包含所有字段，未变化的为 None
    for delta in [
        {"role": "assistant", "content": None, "function_call": None, "tool_calls": None},
        {"role": None, "content": None, "function_call": None,
         "tool_calls": [{"index": 0, "id": "call_1", "type": "function",
                         "function": {"name": "run_code", "arguments": ""}}]},
        {"role": None, "content": None, "function_call": None,
         "tool_calls": [{"index": 0, "function": {"arguments": '{"language"'}}]},
        {"role": None, "content": None, "function_call": None,
         "tool_calls": [{"index": 0, "function": {"arguments": ': "python", "code": "print(42)"}'}}]},
    ]:
        merge_deltas(msg, delta)

    print(f"role: {msg.get('role')}")
    tc = (msg.get("tool_calls") or [{}])[0]
    print(f"tool_calls[0].function.name: {tc.get('function', {}).get('name')}")
    print(f"tool_calls[0].function.arguments: {tc.get('function', {}).get('arguments')}")

    lang, code = extract_code_from_message(msg)
    print(f"extracted: language={lang}, code={code}")

    # ── parse_partial_json 演示 ──────────────────────────────────
    print("\n=== parse_partial_json ===")
    cases = [
        '{"language": "python", "code": "print(1)',
        '{"language": "python", "code": "x = 1\ny = 2"}',
        '{"code": "',
        "",
    ]
    for c in cases:
        print(f"  {c[:50]!r:55s} → {parse_partial_json(c)}")

